from pathlib import Path
p=Path(__file__).resolve().parents[1]/'tests/browser-smoke.mjs'
s=p.read_text()
old="await addNode('beright');await addNode('explain');assert.equal(await page.locator('#brain-graph [data-trigger-hub]').count(),1,'BRAIN projects trigger infrastructure into one hub');assert.equal(await page.locator('#brain-graph .brain-trigger-chip').count(),6,'fixed trigger alphabet remains visible as chips');assert.equal(await page.locator('#brain-graph .brain-stack-node').count(),2,'main stack shows behavioral body without duplicating trigger infrastructure');assert.equal(await page.locator('#brain-graph .brain-stack-edge').count(),1,'body stack renders its behavioral edge before an entry route is authored');assert.equal(await page.locator('#to-setup').isDisabled(),true,'graph remains blocked until the opening trigger is connected');const impulseWrap=page.locator('#brain-graph .brain-stack-node').filter({hasText:'БЫТЬ ПРАВЫМ'}).first(),reactionWrap=page.locator('#brain-graph .brain-stack-node').filter({hasText:'ОБЪЯСНИТЬ'}).first();const impulseId=await impulseWrap.getAttribute('data-brain-node-wrap'),reactionId=await reactionWrap.getAttribute('data-brain-node-wrap');const criticismRow=page.locator('[data-trigger-row]').filter({hasText:'КРИТИКА'}).first(),triggerId=await criticismRow.getAttribute('data-trigger-row');"
new="await addNode('beright');await addNode('explain');assert.equal(await page.locator('#brain-graph [data-trigger-hub]').count(),1,'BRAIN projects trigger infrastructure into one hub');assert.equal(await page.locator('#brain-graph .brain-trigger-chip').count(),6,'fixed trigger alphabet remains visible as chips');assert.equal(await page.locator('#brain-graph .brain-stack-node').count(),2,'main stack shows behavioral body without duplicating trigger infrastructure');assert.equal(await page.locator('#brain-graph .brain-stack-edge').count(),0,'adding nodes never invents a causal edge');assert.equal(await page.locator('#to-setup').isDisabled(),true,'unconnected custom nodes are not runnable');const impulseWrap=page.locator('#brain-graph .brain-stack-node').filter({hasText:'БЫТЬ ПРАВЫМ'}).first(),reactionWrap=page.locator('#brain-graph .brain-stack-node').filter({hasText:'ОБЪЯСНИТЬ'}).first();const impulseId=await impulseWrap.getAttribute('data-brain-node-wrap'),reactionId=await reactionWrap.getAttribute('data-brain-node-wrap');await page.locator(`[data-brain-node=\"${impulseId}\"]`).click();await page.locator(`[data-brain-connect=\"${impulseId}\"]`).click();assert.equal(await page.locator('#brain-graph').getAttribute('data-connect-from'),impulseId,'player explicitly starts a body connection');await page.locator(`[data-brain-target=\"${reactionId}\"]`).click();assert.equal(await page.locator('#brain-graph .brain-stack-edge').count(),1,'explicit connect creates the body causal edge');assert.equal(await page.locator('#to-setup').isDisabled(),true,'body chain still needs the scenario opening trigger');const criticismRow=page.locator('[data-trigger-row]').filter({hasText:'КРИТИКА'}).first(),triggerId=await criticismRow.getAttribute('data-trigger-row');"
if old not in s: raise SystemExit('explicit causality target not found')
